export const EXERCISE_SLUG_SET = new Set<string>(ALL_EXERCISE_SLUGS);

export function getExerciseAvatarUrl(exerciseIdOrSlug: string): string | null {
  const slug = exerciseIdOrSlug.replace(/^apk_/, "");
  if (EXERCISE_SLUG_SET.has(slug)) return `/media/exercises/${slug}_avatar.png`;
  return null;
}

export function getExerciseFullUrl(exerciseIdOrSlug: string): string | null {
  const slug = exerciseIdOrSlug.replace(/^apk_/, "");
  if (EXERCISE_SLUG_SET.has(slug)) return `/media/exercises/${slug}_full.png`;
  return null;
}

const MUSCLE_NAME_TO_GRAPHIC: Record<string, string> = {
  'Abdominals': 'abdominals',
  'Abductors': 'abductors',
  'Adductors': 'adductors',
  'Biceps': 'biceps',
  'Calves': 'calves',
  'Forearms': 'forearms',
  'Front Delt': 'frontdelt',
  'Glutes': 'glutes',
  'Hamstrings': 'hamstrings',
  'Lats': 'lats',
  'Lower Back': 'lowerback',
  'Lower Chest': 'lowerchest',
  'Middle Delt': 'middledelt',
  'Obliques': 'obliques',
  'Quadriceps': 'quadriceps',
  'Rear Delt': 'reardelt',
  'Rotator Cuff': 'reardelt',
  'Traps': 'traps',
  'Triceps': 'triceps',
  'Upper Back': 'upperback',
  'Upper Chest': 'upperchest',
};

export function getMuscleGraphicUrl(muscleName: string, sex: 'Male' | 'Female' = 'Male'): string | null {
  const prefix = sex === "Female" ? "female_muscle_" : "male_muscle_";
  const mapped = MUSCLE_NAME_TO_GRAPHIC[muscleName] ?? muscleName.toLowerCase().replace(/\s+/g, "");
  const key = `${prefix}${mapped}`;
  if (MUSCLE_GRAPHIC_URLS[key]) return MUSCLE_GRAPHIC_URLS[key];
  const found = Object.keys(MUSCLE_GRAPHIC_URLS).find((k) => k.startsWith(prefix) && k.includes(mapped.slice(0, 5)));
  return found ? MUSCLE_GRAPHIC_URLS[found] : null;
}

const TIER_TO_LEAGUE_KEY: Record<string, string> = {
  Rookie: 'wood',
  Novice: 'bronze',
  Intermediate: 'silver',
  Enthusiast: 'gold',
  Veteran: 'plat',
  Elite: 'diamond',
  Champion: 'champion',
  Titan: 'titan',
  Olympian: 'olympian',
};

export function getLeagueBannerUrl(tier: string): string | null {
  const key = TIER_TO_LEAGUE_KEY[tier] ?? tier.toLowerCase();
  return LEAGUE_BANNER_URLS[key] ?? null;
}

export function getSeasonCardUrl(tier: string): string | null {
  const key = TIER_TO_LEAGUE_KEY[tier] ?? tier.toLowerCase();
  return SEASON_CARD_URLS[key] ?? null;
}

export function getRoutineRankUrl(tier: string): string | null {
  const rawKey = TIER_TO_LEAGUE_KEY[tier] ?? tier.toLowerCase();
  const key = rawKey === 'plat' ? 'platinum' : rawKey;
  return ROUTINE_RANK_URLS[key] ?? null;
}
